// Task представляет собой функцию, которая будет выполнена воркером.
// Контекст позволяет отменить выполнение задачи, если пул останавливается.
type Task func(ctx context.Context) error

// Pool реализует пул воркеров с ограничением параллелизма.
// Он принимает задачи из канала и распределяет их между фиксированным
// количеством воркеров.
type Pool struct {
	// tasks — канал, из которого воркеры берут задачи для обработки.
	tasks chan Task

	// wg — WaitGroup для ожидания завершения всех активных задач.
	wg sync.WaitGroup

	// ctx — контекст пула, который отменяется при остановке пула.
	ctx context.Context

	// cancel — функция отмены контекста пула.
	cancel context.CancelFunc

	// workerCount — количество одновременно работающих воркеров.
	workerCount int

	// once — гарантирует, что пул будет остановлен только один раз.
	once sync.Once

	// started — флаг, указывающий, были ли запущены воркеры.
	started bool

	// mu — мьютекс для защиты поля started.
	mu sync.Mutex
}

// NewPool создаёт новый пул воркеров с указанным количеством воркеров.
// Параметры:
//   - workerCount: количество одновременно работающих воркеров (должно быть > 0).
//   - bufferSize: размер буфера канала задач. Если 0, канал небуферизованный.
//
// Возвращает указатель на созданный пул.
func NewPool(workerCount int, bufferSize int) *Pool {
	if workerCount <= 0 {
		workerCount = 1
	}

	ctx, cancel := context.WithCancel(context.Background())

	return &Pool{
		tasks:       make(chan Task, bufferSize),
		ctx:         ctx,
		cancel:      cancel,
		workerCount: workerCount,
	}
}

// Start запускает воркеры пула. Метод идемпотентен: повторные вызовы
// не приводят к запуску дополнительных воркеров.
// Вызывать Start нужно до отправки задач в пул.
func (p *Pool) Start() {
	p.mu.Lock()
	defer p.mu.Unlock()

	if p.started {
		return
	}
	p.started = true

	// Запускаем workerCount горутин-воркеров.
	// Каждая воркер-горутинка бесконечно читает задачи из канала p.tasks
	// и выполняет их, пока канал не будет закрыт или контекст не будет отменён.
	for i := 0; i < p.workerCount; i++ {
		p.wg.Add(1)
		go p.worker()
	}
}

