import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.locks.ReentrantReadWriteLock;

/**
 * Потокобезопасный LRU-кэш с ограничением по памяти.
 * <p>
 * Кэш хранит пары ключ-значение и автоматически вытесняет наименее недавно
 * используемые элементы при превышении лимита памяти.
 * </p>
 * <p>
 * Для отслеживания порядка использования используется двусвязный список,
 * где голова списка — самый недавно использованный элемент, а хвост — самый
 * давно не используемый. При каждом обращении к элементу (get или put) он
 * перемещается в голову списка.
 * </p>
 * <p>
 * Ограничение по памяти учитывает размер ключа, значения и служебных структур
 * данных. При добавлении нового элемента, если текущий размер превышает лимит,
 * вытесняются элементы с конца списка (наименее недавно используемые).
 * </p>
 *
 * @param <K> тип ключей
 * @param <V> тип значений
 */
public class LRUMemoryCache<K, V> {

    /**
     * Внутренний класс узла двусвязного списка.
     * Хранит ключ, значение и ссылки на предыдущий и следующий узлы.
     */
    private static class Node<K, V> {
        K key;
        V value;
        Node<K, V> prev;
        Node<K, V> next;

        Node(K key, V value) {
            this.key = key;
            this.value = value;
        }
    }

    /**
     * Карта для быстрого поиска узла по ключу.
     * Позволяет за O(1) находить узел в двусвязном списке.
     */
    private final Map<K, Node<K, V>> map;

    /**
     * Голова двусвязного списка — самый недавно использованный элемент.
     */
    private Node<K, V> head;

    /**
     * Хвост двусвязного списка — самый давно не используемый элемент.
     */
    private Node<K, V> tail;

    /**
     * Максимальный размер кэша в байтах.
     */
    private final long maxMemoryBytes;

    /**
     * Текущий размер кэша в байтах.
     */
    private long currentMemoryBytes;

    /**
     * Размер служебных структур данных на один элемент кэша в байтах.
     * Включает: объект Node (заголовок объекта + ссылки + поля),
     * запись в HashMap (Entry), и другие накладные расходы.
     * Это приблизительная оценка.
     */
    private static final long OVERHEAD_PER_ENTRY = 128;

    /**
     * Замок для обеспечения потокобезопасности.
     * Используется ReadWriteLock для оптимизации: несколько потоков могут
     * одновременно читать, но запись требует эксклюзивного доступа.
