/**
 * Функция debounce (задержка выполнения).
 * Возвращает новую функцию, которая откладывает вызов оригинальной функции `fn`
 * на указанное количество миллисекунд (`ms`). Если новая функция вызывается
 * повторно до истечения таймера, предыдущий отложенный вызов отменяется,
 * и таймер перезапускается.
 *
 * @param fn - Оригинальная функция, которую нужно "отложить".
 * @param ms - Количество миллисекунд задержки перед выполнением `fn`.
 * @returns Новая функция с той же сигнатурой аргументов, что и `fn`.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера setTimeout.
  // Инициализируется как undefined, так как таймер ещё не установлен.
  let timer: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию-обёртку, которая сохраняет типизацию аргументов
  // оригинальной функции `fn` (через Parameters<T>).
  return (...args: Parameters<T>) => {
    // Если таймер уже установлен (т.е. предыдущий вызов ещё не выполнился),
    // отменяем его, чтобы избежать выполнения устаревшего вызова.
    if (timer) clearTimeout(timer);

    // Устанавливаем новый таймер, который выполнит оригинальную функцию `fn`
    // с переданными аргументами `args` через `ms` миллисекунд.
    timer = setTimeout(() => fn(...args), ms);
  };
}
```

