/// Вычисляет медиану значений в изменяемом векторе вещественных чисел.
/// Возвращает `None`, если вектор пуст, так как медиана не определена.
/// В противном случае возвращает `Some(median)`.
pub fn median(v: &mut Vec<f64>) -> Option<f64> {
    // Если вектор пуст, медиана не существует — возвращаем None.
    if v.is_empty() { return None; }

    // Сортируем вектор по возрастанию.
    // Используем partial_cmp, так как f64 не реализует Ord (из-за NaN).
    // unwrap() здесь безопасен только если в данных нет NaN;
    // в реальных задачах стоит обрабатывать случай с NaN явно.
    v.sort_by(|a, b| a.partial_cmp(b).unwrap());

    // Вычисляем индекс середины отсортированного вектора.
    let m = v.len() / 2;

    // Если количество элементов чётное, медиана — среднее арифметическое
    // двух средних элементов (индексы m-1 и m).
    // Если количество элементов нечётное, медиана — элемент по индексу m.
    Some(if v.len() % 2 == 0 {
        (v[m - 1] + v[m]) / 2.0
    } else {
        v[m]
    })
}
