// Get извлекает значение из кэша по указанному ключу.
//
// Метод потокобезопасен: использует блокировку на чтение (RLock) для доступа
// к внутреннему хранилищу элементов, что позволяет одновременное чтение
// несколькими горутинами.
//
// Поведение:
//   - Если ключ отсутствует в кэше, возвращается пустая строка и false.
//   - Если ключ найден, но срок действия элемента истёк (текущее время позже
//     времени истечения e.expires), возвращается пустая строка и false.
//     Обратите внимание: просроченные элементы не удаляются автоматически
//     при вызове Get; они остаются в памяти до явного удаления или очистки.
//   - Если ключ найден и элемент не просрочен, возвращается значение элемента
//     и true.
//
// Параметры:
//   - key: строковый ключ, по которому выполняется поиск элемента в кэше.
//     Пустая строка допустима как ключ, если она была ранее добавлена.
//
// Возвращаемые значения:
//   - string: значение элемента, если он найден и не просрочен; иначе пустая строка.
//   - bool: true, если элемент найден и действителен; false, если элемент
//     отсутствует или просрочен.
//
// Граничные случаи:
//   - При одновременном доступе нескольких горутин к одному ключу метод
//     корректно обрабатывает конкурентный доступ благодаря мьютексу.
//   - Если элемент был добавлен с уже истёкшим сроком действия, Get вернёт
//     false даже при первом же обращении.
//   - Метод не изменяет состояние кэша (не удаляет просроченные элементы),
//     поэтому при частых запросах к просроченным ключам возможна утечка памяти.
//     Для очистки рекомендуется использовать отдельный метод удаления или
//     фоновую задачу очистки.
//
// Пример использования:
//
//	value, found := cache.Get("user:123")
//	if found {
//	    fmt.Println("Значение:", value)
//	} else {
//	    fmt.Println("Элемент не найден или просрочен")
//	}
func (c *Cache) Get(key string) (string, bool) {
	c.mu.RLock()
	e, ok := c.items[key]
	c.mu.RUnlock()
	if !ok || time.Now().After(e.expires) {
		return "", false
	}
	return e.value, true
}
```

